mapper.update:
UPDATE post_reply r
    INNER JOIN post p ON p.id = r.post_id
SET
    r.content = #{content},
    r.content_document = #{contentDocument,jdbcType=VARCHAR},
    r.version = r.version + 1,
    r.updated_at = CURRENT_TIMESTAMP(6)
WHERE p.board_id = #{boardId}
    AND r.post_id = #{postId}
    AND r.id = #{replyId}
    AND r.version = #{version}
    AND p.deleted_at IS NULL

mapper.delete:
DELETE r
FROM post_reply r
    INNER JOIN post p ON p.id = r.post_id
WHERE p.board_id = #{boardId}
    AND r.post_id = #{postId}
    AND r.id = #{replyId}
    AND r.version = #{version}
    AND p.deleted_at IS NULL

mapper.select:
SELECT p.id AS postId, b.slug AS boardSlug, b.name AS boardName, p.title, m.display_name AS authorDisplayName, p.is_secret AS secret, p.created_at AS createdAt, r.id AS replyId, bp.official_reply_enabled AS officialReplyEnabled
INNER JOIN member m ON m.id = p.author_id WHERE
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit} OFFSET #{offset}
